import{z as A,x as l,o as e,c as s,q as t,j as r,D as E,d as B,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"质量选择与声誉","description":"","frontmatter":{"title":"质量选择与声誉","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/quality-reputation-choosing.md","filePath":"econ/quality-reputation-choosing.md","lastUpdated":1791413859000}'),p={name:"econ/quality-reputation-choosing.md"};function d(c,a,C,h,_,f){const o=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="质量选择与声誉" tabindex="-1">质量选择与声誉 <a class="header-anchor" href="#质量选择与声誉" aria-label="Permalink to &quot;质量选择与声誉&quot;">​</a></h1><div class="epigraph"><p>看不见的质量要看得见的价格来担保：溢价是押在柜台上的抵押品，砸一次招牌就当场没收——债主是顾客。</p><footer>—— 据 Klein and Leffler, AER 1981；Shapiro, JPE 1983 整理</footer></div><p><a href="/econ/advertising-economics">上一课</a>的第三读法把广告接到质量：只有付得起沉淀成本的厂商才做得起广告，花钱本身是信号。本课把质量变成<strong>选择变量</strong>：支付买不到质量本身，只能买历史——厂商的质量选择是一个跨期承诺问题。静态一侧是<a href="/econ/akerlof-lemons">柠檬市场</a>：逆向选择把高质量逐出市场；本课补时间的一侧：声誉如何在重复关系里把质量买回来。<a href="/econ/aftermarket-lockin">后市场锁定</a>课已写过特例——主件沉没后的售后机会主义；本课推广成一般会计：不可观测的质量，要靠一笔可没收的押金担保。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单期市场里，消费者只愿付期望质量的价格：高质量成本 \\(c_H\\)，低质量成本 \\(c_L\\)，二者差 \\(\\Delta c\\) 但售价相同，高质量退出——柠檬均衡。缺口不是把逆向选择重讲一遍，而是问时间如何修复它。做法：让厂商连续多期在同一市场卖，消费者按历史更新对质量的信念；均衡里价格高于高质量的平均成本，溢价流 \\((p-c_H)\\) 每期都在流，而它<strong>只在继续诚实时才流</strong>。削质的激励约束于是写成：</p> \\[p-c_H \\;\\geq\\; \\frac{1-\\delta}{\\delta}\\,\\Delta c . \\]<p>左边是削质会没收的抵押品现值，右边是削质省下的当期成本。折扣越狠（\\(\\delta\\) 越小）或成本差越大，要求的溢价越高。这就是 Klein–Leffler 1981 与 Shapiro 1983 的共同骨架：<strong>溢价不是垄断税，是抵押品的会计需要</strong>；Shapiro 还补了对称的一步——建誉期要亏本卖高价质（押金从亏损里攒出来），溢价是这笔投资的回报率。</p><p><span class="marginnote">术语翻译：这条不等式就是「招牌值多少钱对偷工省多少」。左边是每期溢价折成的现值（砸招牌当场没收的押金），右边是削质一次省下的 \\(\\Delta c\\)。押金越厚，越没人舍得砸。</span></p>',8)),(e(),r(i,null,{default:E(()=>[n(o,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%B4%A8%E9%87%8F%E4%B8%8D%E5%8F%AF%E8%A7%82%E6%B5%8B%22%5D%20--%3E%20PREM%5B%22%E6%BA%A2%E4%BB%B7%E6%B5%81%20p%20%E2%88%92%20c_H%20%E4%BD%9C%E4%B8%BA%E6%8A%B5%E6%8A%BC%22%5D%0A%20%20DEV%5B%22%E5%89%8A%E8%B4%A8%EF%BC%9A%E7%9C%81%20%CE%94c%20%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20CMP%5B%22%E6%AF%94%E8%BE%83%EF%BC%9A%E7%9C%81%E4%B8%8B%E7%9A%84%E4%B8%80%E6%AC%A1%20%E5%AF%B9%20%E6%B2%A1%E6%94%B6%E7%9A%84%E7%8E%B0%E5%80%BC%22%5D%0A%20%20PREM%20--%3E%20CMP%0A%20%20CMP%20--%3E%20KEEP%5B%22%E7%BB%B4%E6%8C%81%E9%AB%98%E8%B4%A8%E9%87%8F%22%5D%0A%20%20CMP%20--%3E%20CRASH%5B%22%E7%A0%B8%E6%8B%9B%E7%89%8C%EF%BC%9A%E6%BA%A2%E4%BB%B7%E6%B8%85%E9%9B%B6%22%5D%0A%20%20KEEP%20--%3E%20HIS%5B%22%E5%8E%86%E5%8F%B2%E6%9B%B4%E6%96%B0%E4%BF%A1%E5%BF%B5%22%5D%0A%20%20CRASH%20--%3E%20HIS%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">折扣因子折算成「未来的期数」更直观：月付市场里 \\(\\delta\\approx 0.99\\) 时，抵押品约等于一百个月的溢价，能担保的成本差高达当期溢价的百倍量级。押金之厚正是溢价之高的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>激励约束给可检验的截面含义。其一，质量越难观测的品类溢价越高、品牌越集中；规格品有便宜的第三方检验，不需要押金——<a href="/econ/information-intermediaries">信息中介</a>的位置由此划清：中介替代押金，押金替代检验。其二，品牌是可转移的抵押：同一块押金担保多条产品线，所以品牌扩张是套保也是透支——把招牌借给低质量延伸品，等于用一份押金担保两笔债。其三，进入者要亏本建誉，进入沉没里多出一项「押金本金」，与<a href="/econ/entry-exit-sunk">进入、退出与沉没成本</a>的 \\(F\\) 对上账。</p><p>动态博弈由 Kreps–Wilson 1982 补齐：有限重复的合作本会被逆向归纳拆掉；只要对手眼里有一点概率遇到「天生诚实」的类型，均衡就会长期维持高质量——声誉的价值来自不完全信息。与<a href="/econ/folk-theorem">无名氏定理</a>的分工：那课说重复<strong>可以</strong>撑住任何个体理性的结果；声誉文献回答的是哪一个结果<strong>被选中</strong>。</p><p><span class="marginnote">数字实例：设 \\(\\Delta c=10\\) 元。顾客大概率回来（\\(\\delta=0.9\\)）时，要求溢价约 \\((1-0.9)/0.9\\times10\\approx1.1\\) 元即可锁住高质量；顾客很可能不来（\\(\\delta=0.5\\)）时，要价跳到 \\(10\\) 元。越没有未来，押金越收不回来——干脆摆烂反而理性。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>抵押会计解释三个反直觉事实。一，高质量厂商愿意「定价过高」且长期不满产：溢价不是市场势力滥用，是抵押品的保管费，降价就等于取回押金。二，事故后的全面召回与超额赔偿，是当众销毁抵押品再重新入金——会计上合理，直觉上难懂。三，游客生意质量普遍差：不是人不诚实，是 \\(\\delta\\) 在「不会再来」下坍缩。<a href="/econ/aftermarket-lockin">后市场锁定</a>的会计在此重逢：锁定压低顾客的退出选项，从而压低有效 \\(\\delta\\)——锁定越深抵押越薄；长期订阅与平台评分，是把 \\(\\delta\\) 抬回的技术。</p>',7)),(e(),r(i,null,{default:E(()=>[n(o,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20TOUR%5B%22%E6%B8%B8%E5%AE%A2%E5%B8%82%E5%9C%BA%3A%20%E4%B8%80%E6%AC%A1%E4%BA%A4%E6%98%93%22%5D%20--%3E%20DELTA%5B%22%E6%9C%89%E6%95%88%20%CE%B4%20%E5%9D%8D%E7%BC%A9%2C%20%E6%8A%BC%E9%87%91%E7%8E%B0%E5%80%BC%E8%B6%8B%E9%9B%B6%22%5D%0A%20%20DELTA%20--%3E%20CHEAT%5B%22%E5%89%8A%E8%B4%A8%E7%9C%81%20%CE%94c%20%E5%8F%88%E4%B8%8D%E8%A2%AB%E7%BD%9A%22%5D%0A%20%20CHEAT%20--%3E%20LOW%5B%22%E8%B4%A8%E9%87%8F%E6%99%AE%E9%81%8D%E5%B7%AE%2C%20%E4%B8%8D%E6%98%AF%E4%BA%BA%E4%B8%8D%E8%AF%9A%E5%AE%9E%22%5D%0A%20%20FIX%5B%22%E8%AF%84%E5%88%86%E4%B8%8E%E8%BF%9E%E9%94%81%E5%93%81%E7%89%8C%22%5D%20--%3E%20MEM%5B%22%E6%8A%8A%E4%B8%80%E6%AC%A1%E4%BA%A4%E6%98%93%E5%8F%98%E5%9B%9E%E5%8F%AF%E8%AE%B0%E5%BF%86%E7%9A%84%E5%8E%86%E5%8F%B2%22%5D%0A%20%20MEM%20--%3E%20LIFT%5B%22%CE%B4%20%E8%A2%AB%E6%8A%AC%E5%9B%9E%2C%20%E6%8A%BC%E9%87%91%E9%87%8D%E6%96%B0%E6%9C%89%E6%95%88%22%5D%0A%20%20LIFT%20--%3E%20GOOD%5B%22%E6%B8%B8%E5%AE%A2%E5%8C%BA%E4%B9%9F%E8%83%BD%E6%9C%89%E9%9D%A0%E8%B0%B1%E5%BA%97%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>错在哪：把品牌溢价直接当反垄断证据——它是润滑剂，除非押金被用来挡检验（抵制评测、收买中介）；反过来把「市场会自己担保质量」说死也不行——押金需要消费者记住历史并协调惩罚，匿名市场里天然失灵。</p><p><span class="marginnote">常见误区：初学者容易把「高质量厂商定价偏高」当成宰客证据。在押金会计里，溢价是担保质量的押金利息：降价等于取回押金、松开诚实做事的约束，反而威胁质量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写品牌估值，不做规制比较；评级与认证是<a href="/econ/information-intermediaries">信息中介</a>的对象，这里只管厂商自己的押金。质量多维时，约束只绑不可观测那一维——可观测维度被过度供给（大堂豪华、床垫一般），不是非理性。声誉均衡依赖惩罚协调，现实惩罚更慢更弱，押金的实际担保力低于折算值。后课默认：质量是承诺问题，声誉是抵押；下一课把承诺问题搬进供应链，问合同写不完时谁来拥有资产。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态柠檬挤走高质；动态声誉用溢价流做抵押修复。</li><li>维持条件：溢价现值 \\(\\geq\\) 削质的一次性节约，折扣与成本差定溢价高度。</li><li>建誉期亏本与定价偏高是抵押会计，不是垄断税；游客市场差在 \\(\\delta\\) 坍缩。</li><li>广告沉淀（上一课）与后市场锁定（锁定压低有效 \\(\\delta\\)）是同一本账的两页。</li><li>出处：Klein–Leffler 1981；Shapiro 1983；Kreps–Wilson 1982。</li></ul>',6))])}const u=A(p,[["render",d]]);export{D as __pageData,u as default};
